sections.solution:
mkdir env-lab && cd env-lab
printf "PORT=\nGREETING=\n" > .env.example
cp .env.example .env
# в .env:
# PORT=4000
# GREETING=Привет
echo ".env" > .gitignore

// app.js
for (const name of ["PORT", "GREETING"]) {
  if (!process.env[name]) {
    console.error(`Нет переменной ${name}. Скопируйте .env.example в .env и заполните.`);
    process.exit(1);
  }
}
console.log(`${process.env.GREETING}, порт ${process.env.PORT}`);

node --env-file=.env app.js
node app.js
git init
git check-ignore -v .env
